<?php
/**  * Job Order Tracker Tab  * Shows job_order and combined transaction types only  */
?>  <div class="tracker-container">  <h2>Job Order Tracker</h2>  <p style="color: #6b7280; margin-bottom: 2rem;">  Track service jobs and combined transactions (service + merchandise).  </p>  <!-- Filters -->  <form method="GET" class="filters">  <input type="hidden" name="tab" value="job_order_tracker">  <div class="filters-grid">  <div class="form-group">  <label for="filter_status">Status</label>  <select name="status" id="filter_status">  <option value="">All Statuses</option>  <option value="Pending" <?= ($_GET['status'] ?? '') === 'Pending' ? 'selected' : '' ?>>Pending</option>  <option value="In Progress" <?= ($_GET['status'] ?? '') === 'In Progress' ? 'selected' : '' ?>>In Progress</option>  <option value="Completed" <?= ($_GET['status'] ?? '') === 'Completed' ? 'selected' : '' ?>>Completed</option>  <option value="Rejected" <?= ($_GET['status'] ?? '') === 'Rejected' ? 'selected' : '' ?>>Rejected</option>  </select>  </div>  <div class="form-group">  <label for="filter_mechanic">Mechanic</label>  <input type="text" name="mechanic" id="filter_mechanic"  value="<?= htmlspecialchars($_GET['mechanic'] ?? '') ?>"  placeholder="Search mechanic name">  </div>  <div class="form-group">  <label for="filter_service_type">Service Type</label>  <input type="text" name="service_type" id="filter_service_type"  value="<?= htmlspecialchars($_GET['service_type'] ?? '') ?>"  placeholder="Search service type">  </div>  <div class="form-group">  <label for="filter_date_from">Date From</label>  <input type="date" name="date_from" id="filter_date_from"  value="<?= htmlspecialchars($_GET['date_from'] ?? '') ?>">  </div>  <div class="form-group">  <label for="filter_date_to">Date To</label>  <input type="date" name="date_to" id="filter_date_to"  value="<?= htmlspecialchars($_GET['date_to'] ?? '') ?>">  </div>  </div>  <div style="display: flex; gap: 1rem; margin-top: 1rem;">  <button type="submit" class="btn btn-primary">Apply Filters</button>  <a href="?tab=job_order_tracker" class="btn btn-secondary">Clear Filters</a>  </div>  </form>  <!-- Job Orders Table -->  <table class="data-table">  <thead>  <tr>  <th>JO Number</th>  <th>Customer</th>  <th>Vehicle</th>  <th>Service Type</th>  <th>Assigned Mechanic</th>  <th>Service Fee</th>  <th>Status</th>  <th>Date Created</th>  </tr>  </thead>  <tbody>  <?php if (empty($job_orders)): ?>  <tr>  <td colspan="8" style="text-align: center; padding: 2rem; color: #6b7280;">  No job orders found  </td>  </tr>  <?php else: ?>  <?php foreach ($job_orders as $jo): ?>  <tr>  <td>  <strong><?= htmlspecialchars($jo['transaction_id']) ?></strong>  </td>  <td><?= htmlspecialchars($jo['customer_name']) ?></td>  <td>  <?php if (!empty($jo['vehicle_plate'])): ?>  <div><?= htmlspecialchars($jo['vehicle_plate']) ?></div>  <div style="font-size: 0.75rem; color: #6b7280;">  <?= htmlspecialchars($jo['vehicle_type'] ?? 'N/A') ?>  </div>  <?php else: ?>  <span style="color: #9ca3af;">—</span>  <?php endif; ?>  </td>  <td><?= htmlspecialchars($jo['service_type']) ?></td>  <td><?= htmlspecialchars($jo['mechanic_name'] ?: 'Unassigned') ?></td>  <td>₱<?= number_format($jo['service_fee'], 2) ?></td>  <td>  <?php  $status = strtolower($jo['status'] ?? 'pending');  $badge_class = 'badge-pending';  if ($status === 'completed') {  $badge_class = 'badge-completed';  } elseif ($status === 'in progress') {  $badge_class = 'badge-progress';  } elseif ($status === 'rejected') {  $badge_class = 'badge-rejected';  }  ?>  <span class="badge <?= $badge_class ?>">  <?= htmlspecialchars(ucfirst($jo['status'])) ?>  </span>  </td>  <td><?= date('M d, Y', strtotime($jo['date_created'])) ?></td>  </tr>  <?php endforeach; ?>  <?php endif; ?>  </tbody>  </table>  <!-- Pagination -->  <?php if ($total_pages > 1): ?>  <div class="pagination">  <?php if ($page > 1): ?>  <a href="?tab=job_order_tracker&page=<?= $page - 1 ?><?= !empty($_GET['status']) ? '&status=' . urlencode($_GET['status']) : '' ?>">  Previous  </a>  <?php endif; ?>  <?php for ($i = 1; $i <= $total_pages; $i++): ?>  <?php if ($i == $page): ?>  <span class="active"><?= $i ?></span>  <?php else: ?>  <a href="?tab=job_order_tracker&page=<?= $i ?><?= !empty($_GET['status']) ? '&status=' . urlencode($_GET['status']) : '' ?>">  <?= $i ?>  </a>  <?php endif; ?>  <?php endfor; ?>  <?php if ($page < $total_pages): ?>  <a href="?tab=job_order_tracker&page=<?= $page + 1 ?><?= !empty($_GET['status']) ? '&status=' . urlencode($_GET['status']) : '' ?>">  Next  </a>  <?php endif; ?>  </div>  <?php endif; ?>
</div>
